package in.tucor.api.buyer;
import in.tucor.api.auth.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.nio.file.*;import java.util.*;
@RestController @RequestMapping("/api/buyer/documents") public class BuyerDocumentController{private final RegistrationDocumentRepository repo;private final Path root;public BuyerDocumentController(RegistrationDocumentRepository r,@Value("${tucor.upload-dir:./uploads/registration}") String dir){repo=r;root=Paths.get(dir).toAbsolutePath().normalize();}
public record Doc(String id,String name,String type,String status,long sizeBytes,String uploadedAt){}
@GetMapping public List<Doc> all(Authentication a){UUID u=UUID.fromString(a.getName());return repo.findAll().stream().filter(d->d.userId.equals(u)).map(d->new Doc(d.id.toString(),d.originalFilename,d.documentType,d.status,d.sizeBytes,d.createdAt.toString())).toList();}
@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Doc upload(Authentication a,@RequestParam String documentType,@RequestPart MultipartFile file)throws IOException{UUID u=UUID.fromString(a.getName());if(file.isEmpty()||file.getSize()>5*1024*1024)throw new IllegalArgumentException("File must be 1 byte to 5MB");String ct=Optional.ofNullable(file.getContentType()).orElse("");if(!List.of("application/pdf","image/jpeg","image/png").contains(ct))throw new IllegalArgumentException("Only PDF, JPEG or PNG allowed");Files.createDirectories(root);RegistrationDocument d=repo.findByUserIdAndDocumentType(u,documentType).orElseGet(RegistrationDocument::new);if(d.storedFilename!=null)Files.deleteIfExists(root.resolve(d.storedFilename));d.userId=u;d.documentType=documentType;d.originalFilename=Optional.ofNullable(file.getOriginalFilename()).orElse("document");d.storedFilename=UUID.randomUUID()+"-"+d.originalFilename.replaceAll("[^A-Za-z0-9._-]","_");d.contentType=ct;d.sizeBytes=file.getSize();d.status="PENDING_REVIEW";Files.copy(file.getInputStream(),root.resolve(d.storedFilename),StandardCopyOption.REPLACE_EXISTING);d=repo.save(d);return new Doc(d.id.toString(),d.originalFilename,d.documentType,d.status,d.sizeBytes,d.createdAt.toString());}
@GetMapping("/{id}/download") public ResponseEntity<Resource> download(Authentication a,@PathVariable UUID id)throws IOException{UUID u=UUID.fromString(a.getName());RegistrationDocument d=repo.findById(id).filter(x->x.userId.equals(u)).orElseThrow();Resource resource=new FileSystemResource(root.resolve(d.storedFilename));return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.contentType)).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+d.originalFilename+"\"").body(resource);}
@DeleteMapping("/{id}") public void delete(Authentication a,@PathVariable UUID id)throws IOException{UUID u=UUID.fromString(a.getName());RegistrationDocument d=repo.findById(id).filter(x->x.userId.equals(u)).orElseThrow();Files.deleteIfExists(root.resolve(d.storedFilename));repo.delete(d);}}